pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount != 10 ether);
        vm.assume(amount <= 1000 ether);

        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.warp(1);

        uint256 beforeTime = c.pastBlockTime();

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");

        uint256 afterTime = c.pastBlockTime();

        assertTrue(afterTime == beforeTime);
    }
}
